		//#region src/client/automation/models.ts
		/** provider 分组目录 → 扁平模型选项。 */
		function flattenGroups(groups) {
			return groups.flatMap((group) => group.models.map((model) => ({
				provider: group.id,
				providerName: group.name,
				id: model.id,
				name: model.name,
				efforts: model.reasoning?.efforts ?? [],
				defaultEffort: model.reasoning?.defaultEffort
			})));
		}
		/**
		* 从 client 上下文构建模型目录读取面。
		* ctx.inject 等待 modelDirectories/sessions 服务就绪后再接线。
		*/
		function createModelSource(ctx) {
			let loadImpl = null;
			try {
				ctx.inject(["modelDirectories", "sessions"], (scope) => {
					const models = scope.modelDirectories;
					const sessions = scope.sessions;
					loadImpl = async () => {
						const sessionId = sessions.currentProvideInfo.getSnapshot()?.sessionId;
						if (sessionId === void 0) return [];
						const directory = models.directoryFor(sessionId);
						try {
							await directory.load();
						} catch {}
						return flattenGroups(directory.store.getSnapshot().groups);
					};
				});
			} catch {
				loadImpl = null;
			}
			return { load: async () => {
				if (loadImpl === null) return [];
				try {
					return await loadImpl();
				} catch {
					return [];
				}
			} };
		}
