		/** 当前语言：跟随 DSH 同步到 <html lang> 的主子标签（缺省 zh）。 */
		function currentLang() {
			try {
				if (document.documentElement.lang.toLowerCase().split("-")[0] === "en") return "en";
			} catch {}
			return "zh";
		}
		/** 轻量翻译：{n} 占位插值。 */
		function makeT() {
			return (key, vars) => {
				let text = DICTS[currentLang()][key] ?? zh[key];
				if (vars !== void 0) for (const [name, value] of Object.entries(vars)) text = text.replaceAll(`{${name}}`, String(value));
				return text;
			};
		}
