		//#region src/client/automation/scheduler.ts
		/** 任务最近一次触发时刻（无记录 = null）。 */
		function latestRunAt(logs, taskId) {
			let latest = null;
			for (const log of logs) {
				if (log.taskId !== taskId) continue;
				if (latest === null || log.createdAt > latest) latest = log.createdAt;
			}
			return latest;
		}
		/** 单次检查：逐任务判定到期并交给 executeTask 真实执行。 */
		function runScheduleTick(deps) {
			const { tasks } = deps.getCatalog();
			if (tasks.length === 0) return;
			const now = Date.now();
			const logs = loadLogs();
			for (const task of tasks) {
				if (task.enabled === false) continue;
				if (deps.isRunning(task.id)) continue;
				if (!isDue(task.schedule ?? DEFAULT_SCHEDULE, latestRunAt(logs, task.id), now)) continue;
				deps.executeTask(task);
			}
		}
		/**
		* 启动调度检查器（立即跑一次 + 60s 周期）；返回清理函数。
		*/
		function startScheduler(deps) {
			runScheduleTick(deps);
			const timer = window.setInterval(() => {
				runScheduleTick(deps);
			}, 6e4);
			return () => {
				window.clearInterval(timer);
			};
		}
